--
-- Table structure for table `order`
--

DROP TABLE IF EXISTS `order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `order_no` varchar(32) NOT NULL,
  `platform` varchar(32) DEFAULT NULL,
  `carrier_code` varchar(32) DEFAULT NULL,
  `carrier_name` varchar(64) DEFAULT NULL,
  `receiver_name` varchar(32) DEFAULT NULL,
  `receiver_phone` varchar(32) DEFAULT NULL,
  `receiver_address` varchar(128) DEFAULT NULL,
  `province` varchar(32) DEFAULT NULL,
  `city` varchar(32) DEFAULT NULL,
  `priority` varchar(16) DEFAULT NULL,
  `pay_time` varchar(19) DEFAULT NULL,
  `expected_delivery_time` varchar(19) DEFAULT NULL,
  `status` varchar(16) DEFAULT NULL,
  `wave_no` varchar(32) DEFAULT NULL,
  `sku_count` int DEFAULT NULL,
  `total_qty` int DEFAULT NULL,
  `amount` decimal(12,2) DEFAULT NULL,
  `buyer_remark` varchar(255) DEFAULT NULL,
  `create_time` varchar(19) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_order_no` (`order_no`)
) ENGINE=InnoDB AUTO_INCREMENT=1908 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

