DROP TABLE IF EXISTS `order_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_item` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `order_no` varchar(32) NOT NULL,
  `line_no` int DEFAULT NULL,
  `sku_code` varchar(32) DEFAULT NULL,
  `sku_name` varchar(128) DEFAULT NULL,
  `spec` varchar(32) DEFAULT NULL,
  `unit` varchar(8) DEFAULT NULL,
  `qty` int DEFAULT NULL,
  `picked_qty` int DEFAULT '0',
  `location_code` varchar(32) DEFAULT NULL,
  `price` decimal(12,2) DEFAULT NULL,
  `amount` decimal(12,2) DEFAULT NULL,
  `remark` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1912 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
