DROP TABLE IF EXISTS `pick_task`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pick_task` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `task_no` varchar(32) NOT NULL,
  `wave_no` varchar(32) DEFAULT NULL,
  `picker_no` varchar(32) DEFAULT NULL,
  `picker_name` varchar(32) DEFAULT NULL,
  `status` varchar(16) DEFAULT NULL,
  `item_count` int DEFAULT NULL,
  `finished_count` int DEFAULT NULL,
  `location_count` int DEFAULT NULL,
  `should_qty` int DEFAULT NULL,
  `actual_qty` int DEFAULT NULL,
  `shortage_qty` int DEFAULT NULL,
  `order_count` int DEFAULT NULL,
  `start_time` varchar(19) DEFAULT NULL,
  `finish_time` varchar(19) DEFAULT NULL,
  `duration_sec` int DEFAULT NULL,
  `path_text` varchar(512) DEFAULT NULL,
  `remark` varchar(255) DEFAULT NULL,
  `create_time` varchar(19) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_task_no` (`task_no`)
) ENGINE=InnoDB AUTO_INCREMENT=781 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
