DROP TABLE IF EXISTS `review`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `review` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `review_no` varchar(32) NOT NULL,
  `wave_no` varchar(32) DEFAULT NULL,
  `order_no` varchar(32) DEFAULT NULL,
  `reviewer_no` varchar(32) DEFAULT NULL,
  `reviewer_name` varchar(32) DEFAULT NULL,
  `status` varchar(16) DEFAULT NULL,
  `should_sku_count` int DEFAULT NULL,
  `should_qty` int DEFAULT NULL,
  `actual_qty` int DEFAULT NULL,
  `diff_type` varchar(16) DEFAULT NULL,
  `diff_qty` int DEFAULT NULL,
  `diff_detail` varchar(512) DEFAULT NULL,
  `pack_material` varchar(16) DEFAULT NULL,
  `package_count` int DEFAULT NULL,
  `weight` decimal(10,2) DEFAULT NULL,
  `start_time` varchar(19) DEFAULT NULL,
  `finish_time` varchar(19) DEFAULT NULL,
  `duration_sec` int DEFAULT NULL,
  `remark` varchar(255) DEFAULT NULL,
  `create_time` varchar(19) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_review_no` (`review_no`)
) ENGINE=InnoDB AUTO_INCREMENT=2017 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
